import functools
import inspect
from typing import ForwardRef, Any, Dict
from fastapi.dependencies.utils import get_typed_signature

# Define a class that will be used as a forward reference
class MyModel:
    pass

# Define a function in a separate "context" (simulated by a different module's globals)
# For simplicity, we'll use a dict as globals.
def original_func(x: 'MyModel'):
    return x

# Wrap it
def wrapper(func):
    @functools.wraps(func)
    def wrapped(x):
        return func(x)
    return wrapped

wrapped_func = wrapper(original_func)

# Now we try to get the typed signature.
# In the real case, the original_func and the wrapper might be in different modules.
# Here they are in the same module, so it might still work even without the fix.
# Let's try to make it fail by manipulating __globals__.

# The issue is that if the wrapped function has its own __globals__, 
# and it's different from the original function's __globals__, 
# and the annotations are forward references that are only in the original function's __globals__.

# Let's simulate different globals.
def create_module_sim():
    globals_dict = {'MyModel': MyModel}
    def func(x: 'MyModel'):
        return x
    func.__globals__ = globals_dict
    return func

original = create_module_sim()
# original.__globals__ is {'MyModel': MyModel}

def wrapper_func(func):
    @functools.wraps(func)
    def wrapped(x):
        return func(x)
    # Simulate wrapped function being in a different module
    wrapped.__globals__ = {'SomethingElse': 1}
    return wrapped

wrapped = wrapper_func(original)
# wrapped.__globals__ is {'SomethingElse': 1}
# wrapped.__annotations__ is {'x': 'MyModel'} (copied from original)

try:
    sig = get_typed_signature(wrapped)
    print("Success!")
    print(sig)
except NameError as e:
    print(f"Caught expected NameError: {e}")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")

